headerConstructor.source:
function GLSHeader(metadata, sessionData, glsServerSessionId, gameId, gameVersion) {
            this.GLSID_CASINARENA = "4";
            this.GLSID_FREEPLAY = "65535";
            this.affiliate = sessionData.getContextID();
            this.freePlay = !metadata.isRealMoney();
            this.gameCodeRGI = metadata.getGameCode();
            this.gameId = gameId;
            this.glsId = (this.freePlay ? this.GLSID_FREEPLAY : this.GLSID_CASINARENA);
            this.langCode = metadata.getLocale();
            this.sessionId = glsServerSessionId;
            this.userId = sessionData.getPlayerID();
            this.version = gameVersion;
            this.promotions = false;
            this.channel = "I";
            this.userType = "C";
            this.currencyCode = "";
        }

freeParser.source:
FreespinParser.prototype.parse = function (input, object) {
            var fsInfo = input.getElementsByTagName("FSInfo")[0];
            if (fsInfo === undefined) {
                return;
            }
            var data = {
                spinNumber: 0,
                spinsTotal: 0,
                extraSpins: 0,
                winning: 0,
                maxWin: false,
                multipliers: undefined,
                removePos: [],
                addValues: [],
                lastSpin: false
            };
            var fsWinningsStr = fsInfo.attributes.getNamedItem("fsWinnings").value;
            var freeSpinsTotalStr = fsInfo.attributes.getNamedItem("freeSpinsTotal").value;
            var freeSpinNumberStr = fsInfo.attributes.getNamedItem("freeSpinNumber").value;
            var isMaxWinStr = fsInfo.attributes.getNamedItem("isMaxWin").value;
            data.spinNumber = parseInt(freeSpinNumberStr);
            data.spinsTotal = parseInt(freeSpinsTotalStr);
            data.lastSpin = (data.spinNumber === data.spinsTotal);
            data.winning = parseInt(fsWinningsStr);
            data.maxWin = (isMaxWinStr === "Y");
            var multipliersNode = input.getElementsByTagName("Multipliers")[0];
            if (multipliersNode) {
                var removePosItem = multipliersNode.attributes.getNamedItem("removePos");
                var addItem = multipliersNode.attributes.getNamedItem("add");
                var multipliersStr = multipliersNode.textContent;
                if (removePosItem) {
                    data.removePos = XMLFilterNumbers(removePosItem.value);
                }
                if (addItem) {
                    data.addValues = XMLFilterNumbers(addItem.value);
                }
                if (multipliersStr && multipliersStr.length > 0) {
                    data.multipliers = XMLFilterNumbers(multipliersStr);
                }
            }
            object.freeSpinData = data;
        };

baseParser.source:
BaseGameParser.prototype.parse = function (input, object) {
            var bgInfo = input.getElementsByTagName("BGInfo")[0];
            if (bgInfo === undefined) {
                return;
            }
            var bgWinnings;
            var bgIsMaxWin;
            var totalWagerWin;
            try {
                bgWinnings = bgInfo.attributes.getNamedItem("bgWinnings").value;
                bgIsMaxWin = bgInfo.attributes.getNamedItem("isMaxWin").value;
                totalWagerWin = bgInfo.attributes.getNamedItem("totalWagerWin").value;
            }
            catch (e) {
                console.warn("!!! Base game parse error !!!");
            }
            var nearWinData = [];
            var nearWinNodes = input.getElementsByTagName("NearPaylineWin");
            if (nearWinNodes) {
                for (var i = 0; i < nearWinNodes.length; i++) {
                    var anticipationNode = nearWinNodes[i];
                    var positionNumbers = sod.XMLFilterNumbers(anticipationNode.textContent);
                    var awardIndex = anticipationNode.attributes.getNamedItem("awardIndex").value;
                    var awardIndexNumber = parseInt(awardIndex);
                    nearWinData.push({
                        positions: positionNumbers,
                        awardIndex: awardIndexNumber
                    });
                }
            }
            var data = {
                winnings: parseInt(bgWinnings),
                isMaxWin: (bgIsMaxWin === "1"),
                totalWagerWin: parseInt(totalWagerWin),
                expandedReels: false,
                featureTrigger: null,
                bgFeature: sod.BaseGameFeatureType.NONE,
                nearWins: nearWinData
            };
            object.baseGameData = data;
        };

playBody.source:
MakePlayRequestCmd.prototype.getEncoders = function () {
            var encoders = _super.prototype.getEncoders.call(this);
            encoders.push(new sod.PlayRequestEncoder(this._wallet.getTotalWagerNumber()));
            if (this._statesModel.getSubGame() == sod.SubGames.BASE_GAME) {
                if (this._forceModel.forceSet) {
                    var forceEncoder = new sod.ForceEncoder(this._forceModel, 0);
                    encoders.push(forceEncoder);
                }
                this._forceModel.reset(true);
            }
            else if (this._statesModel.getSubGame() === sod.SubGames.FREESPIN_GAME) {
                if (this._forceModel.forceSet) {
                    var forceEncoder = new sod.ForceEncoder(this._forceModel, 1);
                    encoders.push(forceEncoder);
                }
                this._forceModel.reset(true);
            }
            return encoders;
        };

freeNext.source:
FreespinSpinCmd.prototype.execute = function () {
            _super.prototype.execute.call(this);
            if (!this._forceModel.forceOpen && !this._forceModel.demoOpen) {
                var totalSpins = this._server.getLogicResponse().freeSpinData.spinsTotal;
                var currentSpin = this._server.getLogicResponse().freeSpinData.spinNumber;
                if (currentSpin == totalSpins) {
                    this.eventDispatcher.dispatchEvent(new sod.GameEvent(sod.GameEvent.STOP_CYCLERS));
                    this._statesModel.changeSubGame(sod.SubGames.FREESPIN_GAME, sod.FreespinStates.TRANSITION_OUT_STATE);
                }
                else {
                    this.eventDispatcher.dispatchEvent(new sod.GameEvent(sod.GameEvent.FS_SPIN));
                }
            }
        };

