filter.source:
function XMLFilterNumbers(sequence, count) {
        var results = [];
        var split = sequence.length > 0 ? sequence.split("|") : [];
        if (count !== undefined && split.length !== count) {
            console.warn("GLM XML Warning: Count does not match number of elements.");
        }
        for (var i = 0; i < split.length; i++) {
            results.push(parseInt(split[i]));
        }
        return results;
    }

jackpotParser.source:
JackpotParser.prototype.parse = function (input, object) {
            var watermarksNode = input.getElementsByTagName("WatermarkPositions")[0];
            if (watermarksNode) {
                var countStr = watermarksNode.textContent.split("|");
                var count = countStr.length;
                var watermarks = sod.XMLFilterNumbers(watermarksNode.textContent, count);
            }
            var jackpotInfo = input.getElementsByTagName("JackpotInfo")[0];
            if (jackpotInfo) {
                var jackpotLevels = jackpotInfo.textContent.split('|').map(function (item) {
                    return parseInt(item, 10);
                });
            }
            var data = {
                jackpotLevels: jackpotLevels,
                watermarks: watermarks,
                award: 0,
                step: 0,
                results: [],
                remainingCoins: undefined
            };
            var coinData = input.getElementsByTagName("CoinData")[0];
            if (coinData && coinData.attributes.getNamedItem("steps")) {
                data.step = parseInt(coinData.attributes.getNamedItem("steps").value);
                for (var child = 0; child < coinData.childNodes.length; child++) {
                    var childNode = coinData.childNodes[child];
                    if (childNode.nodeName === "Coin") {
                        var result = childNode.textContent;
                        data.results.push(parseInt(result));
                    }
                    else if (childNode.nodeName === "Award") {
                        var award = childNode.textContent;
                        data.award = parseInt(award);
                    }
                    else if (childNode.nodeName === "RemainingCoins") {
                        data.remainingCoins = sod.XMLFilterNumbers(childNode.textContent);
                    }
                }
            }
            object.jackpotData = data;
        };

walletCash.source:
BaseGameModel.prototype.updateBalanceAndWins = function () {
            var isMaxWin = this._wallet.isMaxWin();
            var isFunPlay = !this._metadata.isRealMoney();
            var isRecovery = this.isRecovery;
            var isFreespin = this.logicResponse.reelSpinData[0].freeSpin;
            var isJackpot = (this.logicResponse.jackpotData.jackpotLevels !== undefined);
            var isFinalResponse = true;
            var isFeatureTrigger = this.logicResponse.reelSpinData[0].bonusAwarded && !isFreespin;
            if (isFreespin) {
                if (this.logicResponse.freeSpinData.spinNumber !==
                    this.logicResponse.freeSpinData.spinsTotal) {
                    isFinalResponse = false;
                }
            }
            else if (isFeatureTrigger && this.logicResponse.freeSpinData) {
                isFinalResponse = false;
            }
            if (isMaxWin) {
                isFinalResponse = true;
            }
            var isInBasegame = this._statesModel.getSubGame() === sod.SubGames.BASE_GAME;
            var currentState = this._statesModel.getCurrentState().stateName;
            var isInLogicState = (currentState === sod.BaseGameStates.LOGIC_GLS_STATE ||
                currentState === sod.FreespinStates.LOGIC_GLS_STATE ||
                currentState === sod.JackpotStates.LOGIC_GLS_STATE);
            var isComplete = (isInBasegame && !isInLogicState) || isMaxWin;
            var reelSpin = this.getReelSpin();
            var initBalance = this.initResponse.balanceData.getBalance(server.BalanceType.CASH_BALANCE);
            var logicBalance = this.logicResponse.balanceData.getBalance(server.BalanceType.CASH_BALANCE);
            var logicTotalWin = this.logicResponse.gameResultData.totalWin;
            var totalWagerWin = this.logicResponse.baseGameData.totalWagerWin;
            var bgWinnings = this.logicResponse.baseGameData.winnings;
            var reelSpinWins = reelSpin.spinWins;
            if (isRecovery) {
                var balance = initBalance;
                if (isFinalResponse && !isComplete) {
                    balance -= totalWagerWin;
                }
                this._wallet.balance = balance;
            }
            else if (isComplete) {
                this._wallet.balance = logicBalance;
            }
            else if (isInBasegame) {
                if (isFinalResponse) {
                    this._wallet.balance = logicBalance - totalWagerWin;
                }
                else {
                    this._wallet.balance = logicBalance;
                    if (isFunPlay) {
                        this._wallet.balance -= bgWinnings;
                    }
                }
            }
            var baseGameWin = 0.0;
            var featureWin = 0.0;
            var totalWin = 0.0;
            var prevWin = 0.0;
            if (isJackpot) {
                baseGameWin = bgWinnings;
                featureWin = totalWagerWin - bgWinnings;
                totalWin = totalWagerWin;
                prevWin = 0.0;
            }
            else if (isFreespin) {
                featureWin = totalWagerWin - bgWinnings;
                if (isRecovery) {
                    prevWin = featureWin - logicTotalWin;
                }
                else {
                    prevWin = featureWin - reelSpinWins;
                }
            }
            else if (isFeatureTrigger) {
                featureWin = 0.0;
                baseGameWin = 0.0;
                totalWin = 0.0;
                prevWin = 0.0;
            }
            else {
                baseGameWin = totalWagerWin;
                totalWin = totalWagerWin;
                prevWin = 0.0;
            }
            if (isInLogicState) {
                this._wallet.lastWin = prevWin;
                this._wallet.win = prevWin;
            }
            else {
                if (isInBasegame) {
                    this._wallet.lastWin = featureWin;
                    this._wallet.win = totalWagerWin;
                }
                else {
                    this._wallet.lastWin = prevWin;
                    this._wallet.win = featureWin;
                }
            }
            this._wallet.featureWin = featureWin;
            var payloadData = this.logicResponse.payloadData;
            var payloadType = (isComplete ? sgi.PayloadData.TYPE_OUTCOME : sgi.PayloadData.TYPE_WAGER);
            var payload = payloadData ? payloadData[payloadType] : undefined;
            var freeBet = 0.0;
            var cashBalance = 0.0;
            if (payload) {
                this._wallet._payload = true;
            }
            if (payload || !this._wallet._payload) {
                if (isComplete) {
                    if (payload) {
                        cashBalance = payload.CASH;
                        freeBet = payload.FREEBET;
                    }
                    else {
                        cashBalance = this._wallet.balance;
                    }
                    this._wallet.freebetBalance = freeBet;
                    this._wallet.cashBalance = cashBalance;
                }
                else if (isInLogicState && isInBasegame) {
                    if (payload) {
                        cashBalance = payload.CASH;
                        freeBet = payload.FREEBET;
                    }
                    else {
                        cashBalance = this._wallet.balance;
                    }
                    this._wallet.freebetBalance = freeBet;
                    this._wallet.cashBalance = cashBalance;
                }
            }
            if (isMaxWin) {
                this._wallet.lastWin = 0.0;
                this._wallet.win = totalWagerWin;
            }
        };

