BaseGameModel.prototype.setLogicResponse = function (response) {
            var firstResponse = true;
            if (this.logicResponse) {
                firstResponse = false;
            }
            if (this.isRecovery && !firstResponse) {
                this.isRecovery = false;
            }
            this.logicResponse = response;
            this._wallet.setMaxWin(response.baseGameData.isMaxWin);
            var isFreespin = response.reelSpinData[0].freeSpin;
            this._isFreeSpin = isFreespin;
            var isJackpot = (this.logicResponse.jackpotData.jackpotLevels !== undefined);
            this._isJackpot = isJackpot;
            if (this.logicResponse.baseGameData.expandedReels) {
                this.clearAnticipationData();
            }
            else {
                this.fillAnticipationData(isFreespin);
            }
            if (this.isRecovery && firstResponse) {
                this._wallet.handleGameInitialized(true);
            }
            this.updateBalanceAndWins();
        };

