TempleTowerLadderMediator.prototype.onAdded = function () {
            this.view = this.getViewComponent();
            this.addContextListener(sod.GameEvent.SWAP_FROM_TEMPLETOWER, this.onRemoveChildren);
            this.addEventListener(this.view, sod.GameEvent.JACKPOT_WIN_COMPLETE, this.dispatchContextEvent, this);
