TempleTowerTransitionView.prototype._closeDoor = function () {
            this._leftDoor.alpha = this._rightDoor.alpha = 1;
            var timeline = new TimelineMax();
            timeline.fromTo(this._rightDoor, 2.0, {
                "x": 1140
            }, {
                "x": 540
            }, 0.0);
            timeline.fromTo(this._leftDoor, 2.0, {
                "x": -600
            }, {
                "x": 0
            }, 0.0);
            var time = 6.75;
            timeline.call(this._fadeInTally, [], this, 2.0);
            timeline.call(this._fadeOutTally, [], this, 2.0 + time);
            timeline.call(this._openDoor, [], this, 2.0 + time);
            timeline.call(this._swapFromJackpot, [], this, 2.0 + time);
            timeline.call(this._finishTransition, [], this, 3.0 + time);
            this.timelines.push(timeline);
        };

BigWinCmd.prototype.execute = function () {
            _super.prototype.execute.call(this);
            var winData = this._basegameModel.getWinData();
            this._basegameModel.bangUpDuration = 0.0;
            switch (winData.winLevel) {
                case sod.BigWinLevel.NONE:
                    if (winData.coinShower) {
                        this.eventDispatcher.dispatchEvent(new sod.GameEvent(sod.GameEvent.COIN_SHOWER));
                    }
                    var resetFromZero = true;
                    var reelSpin = this._server.getLogicResponse().reelSpinData[0];
                    if (reelSpin.freeSpin) {
                        resetFromZero = false;
                    }
                    var duration = this._bangup.startBangupCalculateDuration(winData.totalWin, sod.LOW_TIER_WIN_MULTIPLIER * this._wallet.getBetNumber(), 'BASEGAME_BANGUP_LOW', 'BASEGAME_BANGUP_END_LOW', resetFromZero, sod.BANG_UP_PROFILE);
                    this._basegameModel.bangUpDuration = duration;
                    this.eventDispatcher.dispatchEvent(new sod.WinMeterEvent(winData.currentWin, duration));
                    this.eventDispatcher.dispatchEvent(new sod.GameEvent(sod.GameEvent.MAIN_SPIN_COMPLETE));
                    break;
                case sod.BigWinLevel.LOW_TIER:
                    this.eventDispatcher.dispatchEvent(new sod.GameEvent(sod.GameEvent.LEGENDARY_WIN));
                    break;
                case sod.BigWinLevel.HIGH_TIER:
                    this.eventDispatcher.dispatchEvent(new sod.GameEvent(sod.GameEvent.EPIC_WIN));
                    break;
                default:
                    this.eventDispatcher.dispatchEvent(new sod.GameEvent(sod.GameEvent.MAIN_SPIN_COMPLETE));
                    console.warn("bad win data");
                    break;
            }
        };

